# Idle screen for the yellow/blue split OLED:
#   "SONGBIRD" in the top ~16px yellow strip, the bird mark (96x48,
#   1-bit MONO_HLSB) in the bottom 48px blue area.
import binascii
import framebuf

_LOGO = binascii.unhexlify(
    ""
)
_fb = framebuf.FrameBuffer(bytearray(_LOGO), 96, 48, framebuf.MONO_HLSB)


def draw_logo(d, status=""):
    d.fill(0)
    d.text("SONGBIRD", 32, 4, 1)      # yellow strip
    d.blit(_fb, 16, 16)               # logo centered in the blue area
    if status:
        d.fill_rect(0, 55, 128, 9, 0)
        d.text(status[:21], 2, 56, 1)
    d.show()
